/**
 * 帮助中心文章模板（`/help/<slug>/`）
 *
 * 由 `gatsby-node.js` 的 `createPages` 从 `src/data/help.js` 生成。
 * 为什么走模板而不是写 N 个手写文件：一族文章结构完全相同、差异全在数据；
 * 写 N 个文件时改一次版式要改 N 处，必然有几篇忘了改（漂移）。
 *
 * 🔴 **版式基调（2026-10-13 定，参考 `www.hellosend.com` 的帮助中心）**：
 *    产品化 how-to —— 先讲这一步给你什么，再给可照做的编号步骤，最后才是边界。
 *    三种内容块各司其职，**别混用**：
 *      - `steps`  = 可照做的操作序列（编号、有顺序要求）⇒ `mk-steps`
 *      - `list`   = 并列的要点 / 清单（无顺序）⇒ `mk-list`
 *      - `note`   = 操作提示（密钥只显示一次、超时别重发）⇒ `mk-note`
 *    ⚠️ **参考风格 ≠ 放宽主张**：HelloSend 那种「✅ Supported Channels」清单可以学，
 *       但它对未实现能力的正面表述我们不能学 —— 见文件头下方那条红线。
 *
 * 🔴 **`scope` 字段不能被省略渲染**。它是 `mk-scope` 提示条，用来把
 *    「这条只在短信通道成立」这类限定写在页面上。
 *    BSP 文案稿 §6 的三条禁令里有两条是「把短信独有的能力写成了通用能力」
 *    —— 这个字段就是那道闸门。**删它之前先回去读 §6。**
 *    ⚠️ 合规限定**永远用 `scope`，不要降级成 `note`**（样式与语义都是刻意分开的）。
 *
 * 🔴 `softwareApp={false}`：help 讲的是 Messaging，不是 Whaleal Cart 那个
 *    Shopify 应用。不传的话 SEO 会声明「本页讲的是一个 Shopify 应用」= 事实错误。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { HELP_ARTICLES, HELP_CATEGORIES } from '../data/help';
import { MESSAGING_CONSOLE_URL, DOCS_URL } from '../constants/brand';
import '../styles/marketing.css';

function Section({ section }) {
  return (
    <section className="mk-section">
      <h2>{section.h}</h2>
      {section.p &&
        section.p.map((para, i) => (
          <p className="mk-section-lead" key={i}>
            {para}
          </p>
        ))}
      {section.steps && (
        <ol className="mk-steps">
          {section.steps.map((step) => (
            <li key={step.h}>
              <h3>{step.h}</h3>
              {step.p && <p>{step.p}</p>}
            </li>
          ))}
        </ol>
      )}
      {section.table && (
        <table className="mk-table">
          <thead>
            <tr>
              {section.table.head.map((h) => (
                <th key={h}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {section.table.rows.map((row) => (
              <tr key={row[0]}>
                {row.map((cell, i) => (
                  <td key={i}>{i === 0 ? <strong>{cell}</strong> : cell}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {section.p2 &&
        section.p2.map((para, i) => (
          <p className="mk-section-lead" key={i}>
            {para}
          </p>
        ))}
      {section.list && (
        <ul className="mk-list">
          {section.list.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      )}
      {section.note && (
        <div className="mk-note">
          <strong>Note.</strong> {section.note}
        </div>
      )}
      {section.scope && (
        <div className="mk-scope">
          <strong>Scope.</strong> {section.scope}
        </div>
      )}
    </section>
  );
}

export default function HelpArticleTemplate({ pageContext }) {
  const { article } = pageContext;
  // 同分类的其它文章优先，不够时按全量补 —— 让「继续读」永远有内容可点。
  const sameCategory = HELP_ARTICLES.filter(
    (a) => a.slug !== article.slug && a.category === article.category
  );
  const fillers = HELP_ARTICLES.filter(
    (a) => a.slug !== article.slug && a.category !== article.category
  );
  const others = [...sameCategory, ...fillers].slice(0, 3);
  const categoryTitle = (HELP_CATEGORIES.find((c) => c.id === article.category) || {}).title;

  return (
    <Layout>
      <SEO
        title={article.title}
        description={article.excerpt}
        pathname={`/help/${article.slug}/`}
        softwareApp={false}
        ogType="article"
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: 'Help', path: '/help/' },
          // 分类层在页面上有、但没有独立 URL ⇒ 只给 name（SEO 组件对该情形省略 item）
          ...(categoryTitle ? [{ name: categoryTitle }] : []),
          { name: article.title, path: `/help/${article.slug}/` },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{categoryTitle}</span>
          <h1>{article.title}</h1>
          <p className="mk-lead">{article.excerpt}</p>
          <p className="mk-meta">
            {article.readMinutes} min read · updated {article.updated}
          </p>
        </header>

        {article.sections.map((section) => (
          <Section section={section} key={section.h} />
        ))}

        <section className="mk-section">
          <h2>Keep reading</h2>
          <div className="mk-grid">
            {others.map((a) => (
              <article className="mk-card" key={a.slug}>
                <h3>{a.title}</h3>
                <p>{a.excerpt}</p>
                <Link className="mk-card-link" to={`/help/${a.slug}/`}>
                  Read this article &rarr;
                </Link>
              </article>
            ))}
          </div>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to="/help/">
              All help topics
            </Link>
            <a className="mk-btn mk-btn-secondary" href={MESSAGING_CONSOLE_URL} target="_blank" rel="noopener noreferrer">
              Open the console
            </a>
            <a className="mk-btn mk-btn-secondary" href={DOCS_URL} target="_blank" rel="noopener noreferrer">
              Technical docs
            </a>
          </div>
        </section>
      </div>
    </Layout>
  );
}
